message:
Invalid `prisma.mod.findMany()` invocation:

{
  where: {
    isApproved: undefined,
    isNSFW: false,
    type: "Mod"
  },
  include: {
    images: {
      select: {
        isPrimary: true,
        isThumbnail: true,
        url: true
      }
    },
    user: {
      select: {
        name: true,
        slug: true,
        imageUrl: true,
        isTrusted: true
      }
    },
    category: {
      select: {
        name: true,
        slug: true
      }
    },
    versions: {
      select: {
        version: true,
        isLatest: true
      },
      orderBy: {
        version: "asc"
      },
      take: 1
    },
    _count: {
      select: {
        favorites: true
      }
    }
  },
  orderBy: {
    lastReleasedAt: "desc"
  },
  skip: NaN,
+ take: Int
}

Argument `take` is missing.
